argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge-R68-OBSERVABILITY-20261014-GPT6'
$expected='1173e893a0b4ded2f92e27b72e99f36f1a96f2ab'
if(([string](& git.exe -C $root rev-parse HEAD)).Trim() -ne $expected){throw 'R68_SOURCE_NOT_EXACT'}
$prod='E:\WebAIBridge'
if(([string](& git.exe -C $prod rev-parse HEAD)).Trim() -ne '66e2ca7681b5e4c4affde9641b69e5582b718f99'){throw 'PRODUCTION_SOURCE_CHANGED'}
$script=Join-Path $root 'app\r68-live-viewer.js'
if(-not(Test-Path -LiteralPath $script)){throw 'R68_VIEWER_MISSING'}
$port=Get-NetTCPConnection -LocalPort 17449 -State Listen -ErrorAction SilentlyContinue
if($port){throw 'R68_PORT_ALREADY_BOUND_MANUAL_RECONCILE'}
$node=(Get-Command node.exe -ErrorAction Stop).Source
$stdout=Join-Path $root 'R68_VIEWER_STDOUT.log'
$stderr=Join-Path $root 'R68_VIEWER_STDERR.log'
if((Test-Path $stdout) -or (Test-Path $stderr)){throw 'OLD_OBSERVER_LOG_EXISTS'}
$env:R68_OBSERVER_DATA_DIR='E:\WebAIBridge\app\data'
$env:R68_OBSERVER_PORT='17449'
$p=Start-Process -FilePath $node -ArgumentList @($script) -WorkingDirectory (Join-Path $root 'app') -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden -PassThru
Write-Output ('OBSERVER_PID='+$p.Id)
$healthy=$false
for($i=0;$i -lt 8;$i++){
 Start-Sleep -Milliseconds 500
 try {
  $j=Invoke-RestMethod -Uri 'http://127.0.0.1:17449/api/live' -Method Get -TimeoutSec 4
  if($j.contract -eq 'bridge.r68.live_chat_observability.v1' -and $j.readOnly -eq $true -and $j.guardrails.noSend -eq $true){
   Write-Output ('R68_HEALTHY='+$true)
   Write-Output ('R68_OPEN_CHATS='+$j.openCount)
   Write-Output ('R68_UNREGISTERED='+$j.unregisteredOpenCount)
   Write-Output ('R68_ASSIGNMENTS='+@($j.assignments).Count)
   Write-Output ('R68_CONFIGURED_CDP_PORTS='+$j.configuredPortCount)
   Write-Output ('R68_SCAN_COMPLETE='+$j.scanComplete)
   $healthy=$true
   break
  }
 } catch {}
}
if(-not $healthy){throw 'R68_OBSERVER_NOT_READY_RECONCILE_PROCESS'}
Write-Output ('PRODUCTION_HEAD_POST='+(& git.exe -C $prod rev-parse HEAD))
Write-Output 'CHROME_NOT_RESTARTED=True'
Write-Output 'BRIDGE_PROCESS_NOT_RESTARTED=True'
